    var body: some View {
        GeometryReader { geo in
            ZStack {
                // Rule of Thirds
                Path { path in
                    let w = geo.size.width
                    let h = geo.size.height

                    path.move(to: CGPoint(x: w/3, y: 0))
                    path.addLine(to: CGPoint(x: w/3, y: h))

