        lightnessChange = 0.0
        red = 0.0; green = 0.0; blue = 0.0
        lowHue = 0.0; lowSaturation = 0.0
        highHue = 0.0; highSaturation = 0.0
        smoothness = 0.0
        homogeneityHue = 0.0; homogeneitySaturation = 0.0; homogeneityLightness = 0.0
