import XCTest
@testable import AppCoreShared
import ImageCore

final class SmartAdjustmentsTests: XCTestCase {

    func testSmartAdjustmentDeltaCalculation() {
        let reference = SmartAdjustmentsReference(exposure: 1.0, kelvin: 5500.0, tint: 10.0)
