    public var smartAdjustmentsDescriptor: SmartAdjustmentsDescriptor? // AI-002

    public init(id: UUID = UUID(), name: String, adjustments: [String: AnyCodable], smartAdjustments: SmartAdjustmentsDescriptor? = nil) {
        self.id = id
