        ])

        let smartPack = StylePack(name: "Smart Adjustments", styles: [
            Style(name: "Smart Portrait Match", adjustments: [:], smartAdjustments: SmartAdjustmentsDescriptor(exposureEnabled: true, whiteBalanceEnabled: true))
