        return [
            mapPackToTree(builtInStyles),
            mapPackToTree(userStyles)
        ]
    }

    private func mapPackToTree(_ pack: StylePack) -> StyleTreeItem {
        var children: [StyleTreeItem] = []

        // Add sub-packs
