    var body: some View {
        ScrollView {
            if importer.discoveredURLs.isEmpty {
                VStack {
                    Spacer()
                    Text("No images found in source.")
                        .foregroundColor(.gray)
                    Spacer()
                }
                .frame(maxWidth: .infinity, minHeight: 400)
