                LazyVGrid(columns: columns, spacing: 10) {
                    ForEach(importer.discoveredURLs, id: \.self) { url in
                        ImportThumbnailCell(url: url, pickedState: importer.pickedState)
                    }
                }
                .padding(15)
            }
        }
